type Parts = [Language, Script | undefined, Region | undefined];
/** `(Option<u64>, Option<u32>, Option<u32>)`: a table value. */
type RawParts = readonly [bigint | undefined, number | undefined, number | undefined];

// crate: unic-langid-impl-0.9.6/src/likelysubtags/mod.rs:7 lang_from_parts
function lang_from_parts(
  input: RawParts,
  lang: Language | undefined,
  script: Script | undefined,
  region: Region | undefined,
): Parts | undefined {
  const lang_ = unwrap(lang ?? (input[0] !== undefined ? Language.from_raw_unchecked(input[0]) : undefined));
  const script_ = script ?? (input[1] !== undefined ? Script.from_raw_unchecked(input[1]) : undefined);
  const region_ = region ?? (input[2] !== undefined ? Region.from_raw_unchecked(input[2]) : undefined);
  return [lang_, script_, region_];
}

// crate: unic-langid-impl-0.9.6/src/likelysubtags/mod.rs:25 maximize
export function maximize(lang: Language, script: Script | undefined, region: Region | undefined): Parts | undefined {
  if (!lang.is_empty() && script !== undefined && region !== undefined) {
    return undefined;
  }

  const l = lang.into_u64();
  if (l !== undefined) {
    if (region !== undefined) {
      const r_ = region.into_u32();
      const result = ok(binary_search_by(tables.LANG_REGION, ([key_l, key_r]) => cmp2(key_l, key_r, l, r_)));
      if (result !== undefined) {
        // safe because all table entries are well formed.
        return lang_from_parts(tables.LANG_REGION[result]![2], undefined, undefined, undefined);
      }
    }

    if (script !== undefined) {
      const s_ = script.into_u32();
      const result = ok(binary_search_by(tables.LANG_SCRIPT, ([key_l, key_s]) => cmp2(key_l, key_s, l, s_)));
      if (result !== undefined) {
        // safe because all table entries are well formed.
        return lang_from_parts(tables.LANG_SCRIPT[result]![2], undefined, undefined, undefined);
      }
    }

    const result = ok(binary_search_by(tables.LANG_ONLY, ([key_l]) => cmp(key_l, l)));
    if (result !== undefined) {
      // safe because all table entries are well formed.
      return lang_from_parts(tables.LANG_ONLY[result]![1], undefined, script, region);
    }
  } else if (script !== undefined) {
    const s = script;
    if (region !== undefined) {
      const r = region;
      const result = ok(binary_search_by(tables.SCRIPT_REGION, ([key_s, key_r]) => cmp2(key_s, key_r, s.into_u32(), r.into_u32())));
      if (result !== undefined) {
        // safe because all table entries are well formed.
        return lang_from_parts(tables.SCRIPT_REGION[result]![2], undefined, undefined, undefined);
      }
    }

    const result = ok(binary_search_by(tables.SCRIPT_ONLY, ([key_s]) => cmp(key_s, s.into_u32())));
    if (result !== undefined) {
      // safe because all table entries are well formed.
      return lang_from_parts(tables.SCRIPT_ONLY[result]![1], undefined, undefined, region);
    }
  } else if (region !== undefined) {
    const r = region;
    const result = ok(binary_search_by(tables.REGION_ONLY, ([key_r]) => cmp(key_r, r.into_u32())));
    if (result !== undefined) {
      // safe because all table entries are well formed.
      return lang_from_parts(tables.REGION_ONLY[result]![1], undefined, undefined, undefined);
    }
  }

  return undefined;
}

// crate: unic-langid-impl-0.9.6/src/likelysubtags/mod.rs:97 minimize
export function minimize(lang: Language, script: Script | undefined, region: Region | undefined): Parts | undefined {
  // maximize returns None when all 3 components are
  // already filled so don't call it in that case.
  let max_langid: Parts;
  if (!lang.is_empty() && script !== undefined && region !== undefined) {
    max_langid = [lang, script, region];
  } else {
    const m = maximize(lang, script, region);
    if (m === undefined) return undefined;
    max_langid = m;
  }

  {
    const trial = maximize(max_langid[0], undefined, undefined);
    if (trial !== undefined) {
      if (parts_eq(trial, max_langid)) {
        return [max_langid[0], undefined, undefined];
      }
    }
  }

  if (max_langid[2] !== undefined) {
    const trial = maximize(max_langid[0], undefined, max_langid[2]);
    if (trial !== undefined) {
      if (parts_eq(trial, max_langid)) {
        return [max_langid[0], undefined, max_langid[2]];
      }
    }
  }

  if (max_langid[1] !== undefined) {
    const trial = maximize(max_langid[0], max_langid[1], undefined);
    if (trial !== undefined) {
      if (parts_eq(trial, max_langid)) {
        return [max_langid[0], max_langid[1], undefined];
      }
    }
  }
  return undefined;
}

/** `(Language, Option<Script>, Option<Region>) == (..)` */
export function parts_eq(a: Parts, b: Parts): boolean {
  return (
    a[0].eq(b[0]) &&
    (a[1] === undefined || b[1] === undefined ? a[1] === b[1] : a[1].eq(b[1])) &&
    (a[2] === undefined || b[2] === undefined ? a[2] === b[2] : a[2].eq(b[2]))
  );
}

function cmp<T extends number | bigint>(a: T, b: T): -1 | 0 | 1 {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** `(&key_a, &key_b).cmp(&(&a, &b))` */
function cmp2<A extends number | bigint, B extends number | bigint>(key_a: A, key_b: B, a: A, b: B): -1 | 0 | 1 {
  const c = cmp(key_a, a);
  return c !== 0 ? c : cmp(key_b, b);
}

function ok(r: Result<number, number>): number | undefined {
  return r.$ === "Ok" ? r._0 : undefined;
}

// PORT: `<[T]>::binary_search_by_key(&b, f)` = `binary_search_by(|k| f(k).cmp(b))`; this is
// `core::slice::binary_search_by` (library/core/src/slice/mod.rs:2982 at the pin), the same
// probe sequence, so which index is found does not depend on the port. (A shared src/std slice
// module would own this; see handoff.)
function binary_search_by<T>(v: readonly T[], f: (x: T) => -1 | 0 | 1): Result<number, number> {
  let size = v.length;
  if (size === 0) {
    return Err(0);
  }
  let base = 0;

  // This loop intentionally doesn't have an early exit if the comparison
  // returns Equal. We want the number of loop iterations to depend *only*
  // on the size of the input slice so that the CPU can reliably predict
  // the loop count.
  while (size > 1) {
    const half = Math.floor(size / 2);
    const mid = base + half;

    const c = f(v[mid]!);

    base = c === 1 ? base : mid;

    size -= half;
  }

  const c = f(v[base]!);
  if (c === 0) {
    return Ok(base);
  } else {
    const result = base + (c === -1 ? 1 : 0);
    return Err(result);
  }
}
